import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import { Plus, Trello, Clock, Star, ArrowRight, Users, Activity, X, Sparkles } from "lucide-react";
import { useAuth } from "../context/AuthContext";
import { useWorkspace } from "../context/WorkspaceContext";
import api from "../utils/api";

const GRADIENTS = [
  "linear-gradient(135deg, #667eea 0%, #764ba2 100%)",
  "linear-gradient(135deg, #f093fb 0%, #f5576c 100%)",
  "linear-gradient(135deg, #4facfe 0%, #00f2fe 100%)",
  "linear-gradient(135deg, #43e97b 0%, #38f9d7 100%)",
  "linear-gradient(135deg, #fa709a 0%, #fee140 100%)",
  "linear-gradient(135deg, #a18cd1 0%, #fbc2eb 100%)",
  "linear-gradient(135deg, #fd7043 0%, #ffcc02 100%)",
  "linear-gradient(135deg, #30cfd0 0%, #330867 100%)",
];

// ─── Board Card ───────────────────────────────────────────────────────────────
const BoardCard = ({ board, onClick }) => {
  const bg = board.background?.value || GRADIENTS[Math.abs(board._id?.charCodeAt(0) || 0) % GRADIENTS.length];

  return (
    <button
      onClick={onClick}
      className="group relative rounded-2xl overflow-hidden h-40 text-left
        transition-all duration-300 hover:scale-[1.03] hover:shadow-2xl hover:shadow-black/50
        focus-visible:ring-2 focus-visible:ring-violet-500"
      style={{ background: bg }}
    >
      {/* Dark overlay */}
      <div className="absolute inset-0 bg-gradient-to-t from-black/60 via-black/10 to-transparent
        group-hover:from-black/40 transition-all duration-300" />

      {/* Star */}
      {board.isStarred && (
        <div className="absolute top-3 right-3">
          <Star size={14} className="text-yellow-300 fill-yellow-300 drop-shadow-sm" />
        </div>
      )}

      {/* Hover arrow */}
      <div className="absolute top-3 right-3 opacity-0 group-hover:opacity-100 transition-all
        translate-x-2 group-hover:translate-x-0 duration-200">
        <ArrowRight size={16} className="text-white/80" />
      </div>

      {/* Content */}
      <div className="absolute inset-0 p-4 flex flex-col justify-between">
        <span className="text-white font-semibold text-sm leading-snug line-clamp-2 drop-shadow-sm">
          {board.title}
        </span>
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-1.5 text-white/70 text-xs">
            <Clock size={10} />
            <span>{new Date(board.lastActivity || board.updatedAt).toLocaleDateString("en-US", { month: "short", day: "numeric" })}</span>
          </div>
          {/* Member stack placeholder */}
          <div className="flex items-center gap-1 text-white/50 text-xs">
            <Users size={10} />
            <span>{board.members?.length || 0}</span>
          </div>
        </div>
      </div>

      {/* Shimmer on hover */}
      <div className="absolute inset-0 opacity-0 group-hover:opacity-100 transition-opacity duration-500
        bg-gradient-to-r from-transparent via-white/5 to-transparent pointer-events-none" />
    </button>
  );
};

// ─── Create Board Card ────────────────────────────────────────────────────────
const CreateBoardCard = ({ onClick }) => (
  <button
    onClick={onClick}
    className="h-40 rounded-2xl border border-dashed border-slate-700/60
      hover:border-violet-500/50 flex flex-col items-center justify-center gap-2
      text-slate-600 hover:text-violet-400 transition-all duration-200
      hover:bg-violet-500/5 group animate-border-glow"
  >
    <div className="w-10 h-10 rounded-xl border border-dashed border-current
      flex items-center justify-center transition-transform group-hover:scale-110 duration-200">
      <Plus size={18} />
    </div>
    <span className="text-sm font-medium">New board</span>
  </button>
);

// ─── Stat Card ────────────────────────────────────────────────────────────────
const StatCard = ({ icon: Icon, label, value, color, delay = 0 }) => (
  <div className="glass rounded-2xl px-5 py-4 flex items-center gap-4
    card-hover animate-count-up"
    style={{ animationDelay: `${delay}ms` }}>
    <div className={`w-10 h-10 rounded-xl flex items-center justify-center flex-shrink-0 ${color}`}>
      <Icon size={18} className="text-white" />
    </div>
    <div>
      <p className="text-2xl font-bold text-white leading-none">{value}</p>
      <p className="text-xs text-slate-500 mt-0.5">{label}</p>
    </div>
  </div>
);

// ─── Live clock ───────────────────────────────────────────────────────────────
const useClock = () => {
  const [time, setTime] = useState(new Date());
  useEffect(() => {
    const id = setInterval(() => setTime(new Date()), 1000);
    return () => clearInterval(id);
  }, []);
  return time;
};

// ─── Home Page ────────────────────────────────────────────────────────────────
const HomePage = () => {
  const { user } = useAuth();
  const { activeWorkspace, fetchWorkspaces } = useWorkspace();
  const navigate = useNavigate();
  const now = useClock();

  const [boards, setBoards] = useState([]);
  const [loadingBoards, setLoadingBoards] = useState(false);
  const [showCreateBoard, setShowCreateBoard] = useState(false);
  const [newBoardTitle, setNewBoardTitle] = useState("");
  const [creating, setCreating] = useState(false);

  useEffect(() => { fetchWorkspaces(); }, []);

  useEffect(() => {
    if (!activeWorkspace) return;
    setLoadingBoards(true);
    api.get(`/workspaces/${activeWorkspace._id}/boards`)
      .then(({ data }) => setBoards(data.boards || []))
      .catch(console.error)
      .finally(() => setLoadingBoards(false));
  }, [activeWorkspace]);

  const handleCreateBoard = async (e) => {
    e.preventDefault();
    if (!newBoardTitle.trim() || !activeWorkspace) return;
    setCreating(true);
    try {
      const { data } = await api.post("/boards", {
        title: newBoardTitle.trim(),
        workspaceId: activeWorkspace._id,
      });
      setBoards((prev) => [data.board, ...prev]);
      setNewBoardTitle("");
      setShowCreateBoard(false);
    } catch (err) {
      console.error("Failed to create board", err);
    } finally {
      setCreating(false);
    }
  };

  const firstName = user?.name?.split(" ")[0] || "there";
  const hour = now.getHours();
  const greeting = hour < 12 ? "Good morning" : hour < 17 ? "Good afternoon" : "Good evening";
  const emoji   = hour < 12 ? "☀️" : hour < 17 ? "⚡" : "🌙";
  const timeStr = now.toLocaleTimeString("en-US", { hour: "2-digit", minute: "2-digit" });

  return (
    <div className="px-8 py-8 max-w-5xl mx-auto space-y-10">

      {/* ── Hero greeting ─────────────────────────────────────────── */}
      <div className="animate-fade-in">
        <div className="flex items-start justify-between flex-wrap gap-4">
          <div>
            <h1 className="text-4xl font-black text-white mb-2 leading-tight">
              {greeting},{" "}
              <span className="gradient-text">{firstName}</span>{" "}
              <span className="text-3xl">{emoji}</span>
            </h1>
            <p className="text-slate-400 text-base">
              {activeWorkspace
                ? <>Working in <span className="text-white font-semibold">{activeWorkspace.name}</span></>
                : "Create or join a workspace to get started."}
            </p>
          </div>
          {/* Live clock */}
          <div className="glass rounded-2xl px-5 py-3 text-right flex-shrink-0">
            <p className="text-2xl font-mono font-bold text-white tracking-tight">{timeStr}</p>
            <p className="text-xs text-slate-500 mt-0.5">
              {now.toLocaleDateString("en-US", { weekday: "long", month: "short", day: "numeric" })}
            </p>
          </div>
        </div>
      </div>

      {activeWorkspace ? (
        <>
          {/* ── Stat cards ──────────────────────────────────────────── */}
          <div className="grid grid-cols-3 gap-4">
            <StatCard icon={Trello}   label="Total boards"   value={boards.length}                    color="bg-gradient-to-br from-violet-500 to-indigo-600" delay={0} />
            <StatCard icon={Users}    label="Members"         value={activeWorkspace.members?.length || 0} color="bg-gradient-to-br from-indigo-500 to-blue-600"   delay={80} />
            <StatCard icon={Activity} label="Active today"    value="—"                                color="bg-gradient-to-br from-emerald-500 to-teal-600"    delay={160} />
          </div>

          {/* ── Boards section ──────────────────────────────────────── */}
          <div className="animate-fade-in">
            <div className="flex items-center justify-between mb-5">
              <div className="flex items-center gap-3">
                <div className="w-8 h-8 rounded-lg bg-violet-500/15 flex items-center justify-center">
                  <Trello size={15} className="text-violet-400" />
                </div>
                <h2 className="text-base font-bold text-white">Boards</h2>
                <span className="px-2 py-0.5 rounded-full bg-slate-800 text-slate-500 text-xs font-medium">
                  {boards.length}
                </span>
              </div>
              {boards.length > 0 && (
                <button
                  onClick={() => setShowCreateBoard(true)}
                  className="flex items-center gap-1.5 text-xs text-slate-400 hover:text-violet-400
                    transition-colors font-medium"
                >
                  <Plus size={13} /> New board
                </button>
              )}
            </div>

            {loadingBoards ? (
              <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4">
                {[...Array(4)].map((_, i) => (
                  <div key={i} className="h-40 rounded-2xl skeleton" />
                ))}
              </div>
            ) : (
              <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4">
                {boards.map((board) => (
                  <BoardCard
                    key={board._id}
                    board={board}
                    onClick={() => navigate(`/boards/${board._id}`)}
                  />
                ))}

                {showCreateBoard ? (
                  <form
                    onSubmit={handleCreateBoard}
                    className="h-40 rounded-2xl glass border border-slate-700/50 p-3
                      flex flex-col gap-2 animate-scale-in"
                  >
                    <div className="flex items-center justify-between mb-1">
                      <span className="text-xs font-semibold text-slate-400">New board</span>
                      <button type="button" onClick={() => setShowCreateBoard(false)}
                        className="p-1 rounded-lg text-slate-600 hover:text-slate-400 transition-colors">
                        <X size={13} />
                      </button>
                    </div>
                    <input
                      autoFocus
                      value={newBoardTitle}
                      onChange={(e) => setNewBoardTitle(e.target.value)}
                      placeholder="Board title…"
                      className="input-field flex-1 text-xs"
                    />
                    <div className="flex gap-2">
                      <button type="submit" disabled={creating || !newBoardTitle.trim()}
                        className="flex-1 py-2 rounded-xl bg-gradient-to-r from-violet-600 to-indigo-600
                          text-white text-xs font-semibold hover:from-violet-500 hover:to-indigo-500
                          disabled:opacity-50 transition-all">
                        {creating ? "Creating…" : "Create"}
                      </button>
                    </div>
                  </form>
                ) : (
                  <CreateBoardCard onClick={() => setShowCreateBoard(true)} />
                )}
              </div>
            )}
          </div>
        </>
      ) : (
        /* ── No workspace empty state ──────────────────────────────── */
        <div className="flex flex-col items-center justify-center py-24 text-center animate-fade-in">
          <div className="relative mb-6">
            <div className="w-20 h-20 rounded-2xl glass flex items-center justify-center text-4xl">
              🏢
            </div>
            <div className="absolute -top-2 -right-2 w-8 h-8 rounded-full
              bg-gradient-to-br from-violet-500 to-indigo-600 flex items-center justify-center">
              <Sparkles size={14} className="text-white" />
            </div>
          </div>
          <h3 className="text-xl font-bold text-white mb-2">No workspace yet</h3>
          <p className="text-slate-400 text-sm mb-8 max-w-xs">
            Create a workspace to start organizing your team's work with Kanban boards and real-time collaboration.
          </p>
          <div className="flex items-center gap-2 px-4 py-2 rounded-full glass text-slate-500 text-xs">
            <span className="w-1.5 h-1.5 rounded-full bg-violet-400 animate-pulse-dot" />
            Use the workspace switcher in the sidebar to get started
          </div>
        </div>
      )}
    </div>
  );
};

export default HomePage;
